if not getattr(sqlite3, "_ua_trace2", False):
    _originalnyy_connect = sqlite3.connect

    class _UaSoedinenie(sqlite3.Connection):
        def __init__(self, *a, **kw):
            sqlite3.Connection.__init__(self, *a, **kw)
            self._ua_baza = os.path.basename(str(a[0] if a else kw.get("database", "?")))
            self._ua_svoya = CEL in self._ua_baza
            self._ua_id = _novyy_id()
            self._ua_t0 = time.time()
            self._ua_kto = _kto(3)
            if self._ua_svoya:
                _dobavit(self._ua_id, self._ua_kto, self._ua_baza, self)
                _zapis("OPEN " + self._ua_id, 0.0, self._ua_baza + " | " + self._ua_kto)

        def commit(self):
            t0 = time.time()
            busy = "?"
            if self._ua_svoya:
                try:
                    busy = self.execute("PRAGMA busy_timeout").fetchone()[0]
                except Exception:
                    pass
            try:
                sqlite3.Connection.commit(self)
            except Exception as e:
                d = time.time() - t0
                _zapis("COMMIT_FAIL", d, self._ua_baza + " | " + self._ua_kto + " | " + repr(e))
                if self._ua_svoya:
                    otchet_o_sboe(d, e, self._ua_kto, busy)
                raise
            d = time.time() - t0
            if self._ua_svoya:
                _zapis("COMMIT_OK " + self._ua_id, d, self._ua_kto)

        def close(self):
            try:
                if self._ua_svoya:
                    _ubrat(self._ua_id)
                    _zapis("CLOSE " + self._ua_id, time.time() - self._ua_t0, self._ua_kto)
            except Exception:
                pass
            sqlite3.Connection.close(self)

    def _ua_connect(*a, **kw):
        if len(a) < 2 and "timeout" not in kw:
            kw["timeout"] = 30.0
        kw.setdefault("factory", _UaSoedinenie)
        con = _originalnyy_connect(*a, **kw)
        try:
            con.execute("PRAGMA busy_timeout=30000")
        except Exception:
            pass
        return con

    sqlite3.connect = _ua_connect
    sqlite3._ua_trace = True
    sqlite3._ua_trace2 = True
    try:
        threading.Thread(target=_sborshchik, daemon=True).start()
    except Exception:
        pass
    try:
        _zapis("ZAPUSK", 0.0, "python" + str(sys.version_info[0]) + "." + str(sys.version_info[1])
               + " | " + " ".join(str(x) for x in sys.argv[:3])[:150])
    except Exception:
        pass


class _Obertka(object):
    def __init__(self, vnutri, kto):
        object.__setattr__(self, "_ua_vnutri", vnutri)
        object.__setattr__(self, "_ua_kto", kto)
        object.__setattr__(self, "_ua_id", _novyy_id())
        object.__setattr__(self, "_ua_t0", time.time())
        object.__setattr__(self, "_ua_busy", "?")
        _dobavit(self._ua_id, kto, "db.connect")
        _zapis("OPEN " + self._ua_id, 0.0, "db.connect | " + kto)

    def __enter__(self):
        c = self._ua_vnutri.__enter__()
        try:
            _privyazat(self._ua_id, c)
            bylo = c.execute("PRAGMA busy_timeout").fetchone()[0]
            if int(bylo) < 30000:
                c.execute("PRAGMA busy_timeout=30000")
                _zapis("BUSY_ISPRAVLEN", 0.0, str(bylo) + " -> 30000 | " + self._ua_kto)
            stalo = c.execute("PRAGMA busy_timeout").fetchone()[0]
            object.__setattr__(self, "_ua_busy", stalo)
        except Exception:
            pass
        return c

    def __exit__(self, *a):
        t0 = time.time()
        _zapis("COMMIT_START " + self._ua_id, 0.0, "busy_timeout=" + str(self._ua_busy) + " | " + self._ua_kto)
        try:
            r = self._ua_vnutri.__exit__(*a)
        except Exception as e:
            d = time.time() - t0
            _ubrat(self._ua_id)
            _zapis("COMMIT_FAIL", d, "db.connect | " + self._ua_kto + " | " + repr(e))
            otchet_o_sboe(d, e, self._ua_kto, self._ua_busy)
            raise
        d = time.time() - t0
        _ubrat(self._ua_id)
        _zapis("COMMIT_OK " + self._ua_id, d, self._ua_kto)
        _zapis("CLOSE " + self._ua_id, time.time() - self._ua_t0, self._ua_kto)
        return r

    def __getattr__(self, imya):
        return getattr(object.__getattribute__(self, "_ua_vnutri"), imya)


def podklyuchit(g):
    try:
        ishodnyy = g.get("connect")
        if not callable(ishodnyy) or getattr(ishodnyy, "_ua_trace", False):
            return False

        def connect_s_trassoy(*a, **kw):
            return _Obertka(ishodnyy(*a, **kw), _kto(3))

        connect_s_trassoy._ua_trace = True
        connect_s_trassoy._ua_ishodnyy = ishodnyy
        g["connect"] = connect_s_trassoy
        _zapis("PODKLYUCHEN", 0.0, "db.connect обёрнут (V2)")
        return True
    except Exception as e:
        _zapis("PODKLYUCHENIE_FAIL", 0.0, repr(e))
        return False

